    "title": "苏轼《醉落魄·离京口作》",
    "book": "俞平伯《唐宋词选释》",
    "pages": "PDF 99",
    "original": "轻云微月",
    "fullOriginal": "轻云微月，二更酒醒船初发。孤城回望苍烟合。记得歌时，不记归时节。\n巾偏扇坠藤床滑，觉来幽梦无人说。此生飘荡何时歇。家在西南，常作东南别。",
    "fullOriginalLabel": "原作全文",
    "meaning": "行旅夜归与思家，不把漂泊愁绪改说成原词庆功。",
    "note": "2026-10-29依据用户补充的实际版本核读原文及相关题解／注释。原作转简体，标点作阅读整理；祝酒文字为独立整理。",
