    "book": "俞平伯《唐宋词选释》",
    "pages": "PDF 99—100",
    "original": "归路晚风清",
    "fullOriginal": "回首乱山横，不见居人只见城。谁似临平山上塔，亭亭，迎客西来送客行。\n归路晚风清，一枕初寒梦不成。今夜残灯斜照处，荧荧，秋雨晴时泪不晴。",
    "fullOriginalLabel": "原作全文",
    "meaning": "送陈襄离杭，后片含愁；借归路珍重，不预报今晚天气。",
    "note": "2026-10-29依据用户补充的实际版本核读原文及相关题解／注释。原作转简体，标点作阅读整理；祝酒文字为独立整理。",
    "form": "词",
