    "pages": "PDF 105",
    "original": "日高人渴漫思茶，敲门试问野人家。",
    "fullOriginal": "簌簌衣巾落枣花，村南村北响缲车，牛衣古柳卖黄瓜。\n酒困路长惟欲睡，日高人渴漫思茶，敲门试问野人家。",
    "fullOriginalLabel": "原作全文",
