    "pages": "PDF 105",
    "original": "日暖桑麻光似泼，风来蒿艾气如薰。",
    "fullOriginal": "软草平莎过雨新，轻沙走马路无尘，何时收拾耦耕身。\n日暖桑麻光似泼，风来蒿艾气如薰，使君元是此中人。",
