    "title": "苏轼《浣溪沙·游蕲水清泉寺》",
    "book": "俞平伯《唐宋词选释》",
    "pages": "PDF 106",
    "original": "谁道人生无再少",
    "fullOriginal": "游蕲水清泉寺，寺临兰溪，溪水西流。\n山下兰芽短浸溪，松间沙路净无泥，萧萧暮雨子规啼。\n谁道人生无再少，门前流水尚能西，休将白发唱黄鸡。",
    "fullOriginalLabel": "原作全文",
    "meaning": "见溪水西流而振作，非返老还童；不以年龄取笑长辈。",
