    "title": "苏轼《卜算子·黄州定慧院寓居作》",
    "book": "俞平伯《唐宋词选释》",
    "pages": "PDF 109",
    "original": "谁见幽人独往来，缥缈孤鸿影。",
    "fullOriginal": "缺月挂疏桐，漏断人初静。谁见幽人独往来，缥缈孤鸿影。\n惊起却回头，有恨无人省。拣尽寒枝不肯栖，寂寞沙洲冷。",
    "fullOriginalLabel": "原作全文",
    "meaning": "孤鸿寄托孤独自守；不把原作说成欢乐宴饮，只引出愿人被理解的编辑祝愿。",
    "note": "2026-10-29依据用户补充的实际版本核读原文及相关题解／注释。原作转简体，标点作阅读整理；祝酒文字为独立整理。",
