    "title": "秦观《鹊桥仙·纤云弄巧》",
    "book": "俞平伯《唐宋词选释》",
    "pages": "PDF 116",
    "original": "金风玉露一相逢，便胜却人间无数。",
    "fullOriginal": "纤云弄巧，飞星传恨，银汉迢迢暗度。金风玉露一相逢，便胜却人间无数。\n柔情似水，佳期如梦，忍顾鹊桥归路。两情若是久长时，又岂在朝朝暮暮。",
    "fullOriginalLabel": "原作全文",
    "meaning": "七夕牛女相会的爱情词；初识不许诺久长，不把传说当史实。",
    "note": "2026-10-29依据用户补充的实际版本核读原文及相关题解／注释。原作转简体，标点作阅读整理；祝酒文字为独立整理。",
