    "title": "秦观《蝶恋花·晓日窥轩双燕语》",
    "book": "俞平伯《唐宋词选释》",
    "pages": "PDF 116—117",
    "original": "持酒劝云云且住",
    "fullOriginal": "晓日窥轩双燕语，似与佳人，共惜春将暮。屈指艳阳都几许，可无时霎闲风雨。\n流水落花无问处，只有飞云，冉冉来还去。持酒劝云云且住，凭君碍断春归路。",
    "fullOriginalLabel": "原作全文",
    "meaning": "拟人留云以惜春，非实际天气；不把惜春写成必定成功的承诺。",
    "note": "2026-10-29依据用户补充的实际版本核读原文及相关题解／注释。原作转简体，标点作阅读整理；祝酒文字为独立整理。",
