    "title": "周邦彦《苏幕遮·燎沉香》",
    "book": "俞平伯《唐宋词选释》",
    "pages": "PDF 122",
    "original": "水面清圆，一一风荷举。",
    "fullOriginal": "燎沉香，消溽暑。鸟雀呼晴，侵晓窥檐语。叶上初阳干宿雨，水面清圆，一一风荷举。\n故乡遥，何日去，家住吴门，久作长安旅。五月渔郎相忆否？小楫轻舟，梦入芙蓉浦。",
    "fullOriginalLabel": "原作全文",
    "meaning": "夏荷与思乡，故乡友伴之念；借意象不造今天有荷塘。",
    "note": "2026-10-29依据用户补充的实际版本核读原文及相关题解／注释。原作转简体，标点作阅读整理；祝酒文字为独立整理。",
