    "title": "辛弃疾《清平乐·村居》",
    "book": "俞平伯《唐宋词选释》",
    "pages": "PDF 164—165",
    "original": "醉里吴音相媚好，白发谁家翁媪。",
    "fullOriginal": "茅檐低小，溪上青青草。醉里吴音相媚好，白发谁家翁媪。\n大儿锄豆溪东，中儿正织鸡笼。最喜小儿无赖，溪头看剥莲蓬。",
    "fullOriginalLabel": "原作全文",
    "meaning": "描绘乡村家庭，翁媪指老人，无赖作顽皮解；不默认用户子女人数。",
