    "title": "辛弃疾《西江月·遣兴》",
    "book": "俞平伯《唐宋词选释》",
    "pages": "PDF 167",
    "original": "醉里且贪欢笑，要愁那得工夫。",
    "fullOriginal": "醉里且贪欢笑，要愁那得工夫。近来始觉古人书，信著全无是处。\n昨夜松边醉倒，问松我醉何如？只疑松动要来扶，以手推松曰“去”。",
    "fullOriginalLabel": "原作全文",
    "meaning": "醉态拟人含自嘲；不宣扬饮醉、读书无用，也不把原作看作单纯劝乐。",
    "note": "2026-10-29依据用户补充的实际版本核读原文及相关题解／注释。原作转简体，标点作阅读整理；祝酒文字为独立整理。",
