  "r04-ci-22": {
    "id": "r04-ci-22",
    "title": "辛弃疾《贺新郎·甚矣吾衰矣》",
    "book": "俞平伯《唐宋词选释》",
    "pages": "PDF 175—176",
    "original": "知我者，二三子。",
    "fullOriginal": "邑中园亭，仆皆为赋此词。一日独坐停云，水声山色，竞来相娱，意溪山欲援例者，遂作数语，庶几仿佛渊明思亲友之意云。\n甚矣吾衰矣。怅平生交游零落，只今余几。白发空垂三千丈，一笑人间万事。问何物能令公喜？我见青山多妩媚，料青山见我应如是。情与貌，略相似。\n一尊搔首东窗里，想渊明停云诗就，此时风味。江左沉酣求名者，岂识浊醪妙理。回首叫云飞风起。不恨古人吾不见，恨古人不见吾狂耳。知我者，二三子。",
    "fullOriginalLabel": "原作全文",
    "meaning": "思亲友与自许相杂；二三子指朋友，不译成只有两三位，不预设交游零落。",
    "note": "2026-10-29依据用户补充的实际版本核读原文及相关题解／注释。原作转简体，标点作阅读整理；祝酒文字为独立整理。",
    "form": "词",
    "excerpts": [
      "知我者，二三子。"
    ]
  },
