    "original": "春水碧于天，画船听雨眠。",
    "fullOriginal": "人人尽说江南好，游人只合江南老。春水碧于天，画船听雨眠。\n炉边人似月，皓腕凝霜雪。未老莫还乡，还乡须断肠。",
