    "title": "《世说新语·德行第八则》元方季方难为兄弟",
    "book": "刘义庆著、刘孝标注、余嘉锡笺疏《世说新语笺疏》",
    "pages": "PDF 19",
    "original": "元方难为兄，季方难为弟。",
    "fullOriginal": "陈元方子长文有英才，与季方子孝先，各论其父功德，争之不能决，咨于太丘。太丘曰：“元方难为兄，季方难为弟。”",
    "fullOriginalLabel": "故事所在条目原文 · 完整条目",
