    "original": "敕船官悉录锯木屑，不限多少。",
    "fullOriginal": "陶公性检厉，勤于事。作荆州时，敕船官悉录锯木屑，不限多少，咸不解此意。后正会，值积雪始晴，听事前除雪后犹湿，于是悉用木屑覆之，都无所妨。官用竹皆令录厚头，积之如山。后桓宣武伐蜀，装船，悉以作钉。又云：尝发所在竹篙，有一官长连根取之，仍当足，乃超两阶用之。",
    "fullOriginalLabel": "故事所在条目原文 · 完整条目",
