    "fullOriginal": "谢安南免吏部尚书还东，谢太傅赴桓公司马出西，相遇破冈。既当远别，遂停三日共语。太傅欲慰其失官，安南辄引以它端。虽信宿中涂，竟不言及此事。太傅深恨在心未尽，谓同舟曰：“谢奉故是奇士。”",
    "fullOriginalLabel": "故事所在条目原文 · 完整条目",
