    "book": "刘义庆著、刘孝标注、余嘉锡笺疏《世说新语笺疏》",
    "pages": "PDF 628—629",
    "original": "客主不交一言。",
    "fullOriginal": "王子猷出都，尚在渚下。旧闻桓子野善吹笛，而不相识。遇桓于岸上过，王在船中，客有识之者云：“是桓子野。”王便令人与相闻云：“闻君善吹笛，试为我一奏。”桓时已贵显，素闻王名，即便回下车，踞胡床，为作三调。弄毕，便上车去。客主不交一言。",
