    "title": "《世说新语·简傲第十六则》王子猷过门看竹",
    "book": "刘义庆著、刘孝标注、余嘉锡笺疏《世说新语笺疏》",
    "pages": "PDF 641—642",
    "original": "乃留坐，尽欢而去。",
    "fullOriginal": "王子猷尝行过吴中，见一士大夫家，极有好竹。主已知子猷当往，乃洒埽设施，在听事坐相待。王肩舆径造竹下，讽啸良久。主已失望，犹冀还当通，遂直欲出门。主人大不堪，便令左右闭门不听出。王更以此赏主人，乃留坐，尽欢而去。",
    "fullOriginalLabel": "故事所在条目原文 · 完整条目",
