    "full": "《诗经·伐木》写道：“嘤其鸣矣，求其友声。”鸟尚且寻找应和的声音，人也盼有人肯听。敬咱们，有高兴事能分享，有烦心事也不必一个人憋着。\n这杯敬朋友，愿有空常聚，见面常有新话。",
