    "title": "把相见看重",
    "short": "借《诗经》的一句：“鲜我觏尔，我心写兮。”原诗写新婚，我只借相见后心里舒展的那份高兴。今天认识你，很愉快；接下来就慢慢聊，不着急。",
    "full": "借《诗经》的一句：“鲜我觏尔，我心写兮。”原诗写新婚，我只借相见后心里舒展的那份高兴。今天认识你，很愉快；接下来就慢慢聊，不着急。\n这杯敬今天这一面，愿彼此都轻松，也都真诚。",
    "english": "To a meeting that leaves us smiling, with no need to rush what comes next.",
    "translation": "愿相见有笑，也不必急着安排以后。",
