    "title": "日子有生机 · 再说一句",
    "short": "忙归忙，也愿各位别只顾着赶路。这杯敬认真做事的人，愿辛劳有回响，休息也能理直气壮。借诗词中的一句：“日暖桑麻光似泼，风来蒿艾气如薰。”",
    "full": "忙归忙，也愿各位别只顾着赶路。这杯敬认真做事的人，愿辛劳有回响，休息也能理直气壮。\n苏轼在《浣溪沙·软草平莎过雨新》里写道：“日暖桑麻光似泼，风来蒿艾气如薰。”这杯敬各位，愿共事有信任，日子有奔头。",
    "english": "To noticing small signs of life and making room to enjoy them. Here is to another good day together.",
    "translation": "愿看见日常的生机，也有空慢慢欣赏。也盼再有同聚的好日子。",
    "kind": "引句后整理",
    "tone": "poetic",
    "delivery": "spoken",
    "theme": "verse-1",
    "tip": "乡村田园与归耕之念；借日常生机，不称所在地点为田庄。",
    "teaLine": "我以茶代酒，心意一样真。",
    "englishTeaLine": "With tea in my cup and the same warm wishes.",
    "topics": [
      "any"
    ]
