    "title": "兴致不分早晚",
    "short": "借苏轼的一句：“谁道人生无再少”苏轼这句，我想借来敬您：喜欢的事，什么时候开始都不嫌晚。愿您有精神，也有闲心，把日子过得有兴致。",
    "full": "借苏轼的一句：“谁道人生无再少”苏轼这句，我想借来敬您：喜欢的事，什么时候开始都不嫌晚。愿您有精神，也有闲心，把日子过得有兴致。\n这杯敬您，愿舒心常在，笑口常开。",
    "english": "To keeping our curiosity alive, whatever our age.",
    "translation": "愿好奇与兴致，不因年岁而消退。",
