    "title": "给忙碌留一点空",
    "short": "苏轼写过：“敲门都不应，倚杖听江声。”词里门没敲开，倒听见了江声。今天也愿咱们从忙碌里退开一小会儿，把朋友的话听清，把这顿饭吃香。",
    "full": "苏轼写过：“敲门都不应，倚杖听江声。”词里门没敲开，倒听见了江声。今天也愿咱们从忙碌里退开一小会儿，把朋友的话听清，把这顿饭吃香。\n这杯敬朋友，愿有空常聚，见面常有新话。",
    "english": "To stepping out of the rush and hearing each other properly.",
    "translation": "愿暂缓忙碌，好好听彼此说话。",
