    "short": "苏轼在《卜算子·黄州定慧院寓居作》里写道：“谁见幽人独往来，缥缈孤鸿影。”这阕词写得孤清，所以今天更想敬身边的朋友：愿你想说的话有人肯听，安静的时候，也有人懂得不催。",
    "full": "苏轼在《卜算子·黄州定慧院寓居作》里写道：“谁见幽人独往来，缥缈孤鸿影。”这阕词写得孤清，所以今天更想敬身边的朋友：愿你想说的话有人肯听，安静的时候，也有人懂得不催。\n这杯敬朋友，愿有空常聚，见面常有新话。",
