    "short": "借这则旧事勉励咱们自己：承诺以前想清楚，答应以后认真做。敬各位，愿往后合作有信任，遇事有商量。借这则旧事的一句：“既已纳其自托，宁可以急相弃邪？”",
    "full": "借这则旧事勉励咱们自己：承诺以前想清楚，答应以后认真做。敬各位，愿往后合作有信任，遇事有商量。\n《世说新语》里记载：“既已纳其自托，宁可以急相弃邪？”这杯敬各位，愿共事有信任，日子有奔头。",
    "english": "To promises made carefully and kept with care. Here is to another good day together.",
    "translation": "愿慎重承诺，也认真履行。也盼再有同聚的好日子。",
